import datetime,json,os,pathlib,subprocess,time

def run(args):
 p=subprocess.run(args,capture_output=True,text=True,timeout=15)
 if p.returncode:raise RuntimeError(f'{args[0]} exit {p.returncode}')
 return p.stdout.strip()
def utc():return datetime.datetime.now(datetime.timezone.utc).isoformat()
pg=run(['docker','ps','-q','--filter','label=com.docker.compose.service=postgres','--filter','label=com.docker.compose.project=ganso-market'])
queries=[]
def sql(label,q):
 t=time.monotonic();p=subprocess.run(['docker','exec','-e','PGOPTIONS=-c default_transaction_read_only=on -c statement_timeout=2000 -c lock_timeout=500 -c max_parallel_workers_per_gather=0 -c application_name=data01-observer',pg,'psql','-XAt','-v','ON_ERROR_STOP=1','-U','ganso_market','-d','ganso_market','-c',q],capture_output=True,text=True,timeout=10)
 queries.append({'label':label,'utc':utc(),'elapsed_s':time.monotonic()-t,'sql':q,'exit':p.returncode,'error':p.stderr.strip() if p.returncode else None})
 return json.loads(p.stdout) if p.returncode==0 else None
solana=sql('solana_exists',"SELECT json_build_object('domain_events',EXISTS(SELECT 1 FROM domain_events LIMIT 1),'event_quarantine',EXISTS(SELECT 1 FROM event_quarantine LIMIT 1),'bonding_curve_state',EXISTS(SELECT 1 FROM bonding_curve_state LIMIT 1),'pumpswap_pool_state',EXISTS(SELECT 1 FROM pumpswap_pool_state LIMIT 1))")
sonda=sql('sonda_market',"SELECT COALESCE(json_agg(row_to_json(x)),'[]'::json) FROM (SELECT condition_id,active,closed FROM polymarket_markets WHERE condition_id='0xsonda' LIMIT 1)x")
orders=sql('bounded_orders',"SELECT COALESCE(json_agg(row_to_json(x)),'[]'::json) FROM (SELECT status,count(*) sample_rows,min(created_at) sample_oldest,max(created_at) sample_latest FROM (SELECT status,created_at FROM paper_orders ORDER BY order_id LIMIT 200)o GROUP BY status)x")
paths=['/opt/ganso-market/.deploy/backups','/opt/ganso-market/.deploy/incoming','/var/lib/ganso/shadow-replay','/var/lib/ganso/recorder-watchdog']
artifacts=[]
for root in paths:
 p=pathlib.Path(root);item={'path':root,'exists':p.exists()}
 if p.exists():
  item['entries']=[]
  for f in sorted(p.iterdir())[:200]:
   s=f.lstat();row={'path':str(f),'mtime_utc':datetime.datetime.fromtimestamp(s.st_mtime,datetime.timezone.utc).isoformat(),'is_symlink':f.is_symlink()}
   if f.is_file():row.update(bytes=s.st_size,allocated_bytes=s.st_blocks*512)
   elif f.is_dir() and not f.is_symlink() and root.endswith('/backups'):
    row['du_allocated_bytes']=int(run(['du','-sx','-B1',str(f)]).split()[0])
    sha=f/'deploy/release-sha'
    if sha.is_file():row['release']=sha.read_text().strip()
   item['entries'].append(row)
 artifacts.append(item)
print(json.dumps({'utc':utc(),'solana_exists':solana,'sonda':sonda,'bounded_orders':orders,'artifacts':artifacts,'queries':queries},indent=2))
